import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { autopilotAuditEntrySchema, autopilotRunRecordSchema, type AutopilotAuditEntry, type AutopilotRunRecord } from '@kai/contracts';

function fileFor(directory: string, studioProjectId: string): string {
  // Studio project ids are generated by KAI; still refuse anything that is not a plain file name.
  if (!/^[\w.-]+$/.test(studioProjectId)) throw new Error('Invalid studio project id.');
  return path.join(directory, `${studioProjectId}.json`);
}

/**
 * One small file per running Autopilot, written when it starts and removed when it settles.
 *
 * This is `RecoveryStore`'s shape for the board's own loop, and for the same reason: the status lives in memory and
 * dies with the process, so without this a close mid-card left the person with nothing to go on and the board
 * holding a card claimed by an Autopilot that no longer existed. Any file present at startup is a run that was
 * interrupted, which is all the next launch needs to offer to carry on or to put the card back.
 */
export class AutopilotRunStore {
  constructor(private readonly directory: string) {}

  async begin(record: Omit<AutopilotRunRecord, 'schemaVersion'>): Promise<void> {
    await this.write({ ...record, schemaVersion: 1 });
  }

  /** Records what the run is on now, so an interrupted one is reported against the card it was actually holding. */
  async touch(studioProjectId: string, lastMessage: string, now: Date = new Date()): Promise<void> {
    const current = await this.read(studioProjectId);
    if (!current) return;
    await this.write({ ...current, updatedAt: now.toISOString(), lastMessage: lastMessage.slice(0, 600) });
  }

  async end(studioProjectId: string): Promise<void> {
    await fs.rm(fileFor(this.directory, studioProjectId), { force: true });
  }

  /** Keeps a compact append-only audit trail after the live recovery record is removed. */
  async audit(entry: Omit<AutopilotAuditEntry, 'schemaVersion'>): Promise<void> {
    const parsed = autopilotAuditEntrySchema.parse({ ...entry, schemaVersion: 1 });
    const directory = path.join(this.directory, 'history');
    await fs.mkdir(directory, { recursive: true });
    const target = fileFor(directory, parsed.projectId).replace(/\.json$/, '.jsonl');
    await fs.appendFile(target, `${JSON.stringify(parsed)}\n`, 'utf8');
  }

  async listAudit(projectId: string, limit = 100): Promise<AutopilotAuditEntry[]> {
    const target = fileFor(path.join(this.directory, 'history'), projectId).replace(/\.json$/, '.jsonl');
    const raw = await fs.readFile(target, 'utf8').catch(() => '');
    return raw.split('\n').filter(Boolean).slice(-limit).flatMap((line) => {
      try { return [autopilotAuditEntrySchema.parse(JSON.parse(line))]; } catch { return []; }
    });
  }

  async read(studioProjectId: string): Promise<AutopilotRunRecord | null> {
    try {
      return autopilotRunRecordSchema.parse(JSON.parse(await fs.readFile(fileFor(this.directory, studioProjectId), 'utf8')));
    } catch {
      return null;
    }
  }

  /** Newest first. Unreadable or corrupt files are skipped, never fatal at startup. */
  async list(): Promise<AutopilotRunRecord[]> {
    let names: string[];
    try {
      names = await fs.readdir(this.directory);
    } catch {
      return [];
    }
    const records = await Promise.all(
      names.filter((name) => name.endsWith('.json')).map((name) => this.read(path.basename(name, '.json'))),
    );
    return records
      .filter((record): record is AutopilotRunRecord => record !== null)
      .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  }

  private async write(record: AutopilotRunRecord): Promise<void> {
    await fs.mkdir(this.directory, { recursive: true });
    const target = fileFor(this.directory, record.studioProjectId);
    const temporary = `${target}.tmp`;
    await fs.writeFile(temporary, JSON.stringify(autopilotRunRecordSchema.parse(record)), 'utf8');
    await fs.rename(temporary, target);
  }
}
